-- Real Tier 1 content for Topic I.I — The Psychology of Spending.
-- First end-to-end content load: 4 subtopics, their slides, and their questions.
-- Fixed UUIDs for topic/subtopic rows so this migration is safe to re-run
-- (slides/questions are not re-run-safe -- this is a single-shot content load,
-- same as the schema migrations before it).

-- Question ordering wasn't in the original schema; needed so a subtopic's
-- questions render in the intended sequence (Q1, Q2, Q3...).
alter table questions
  add column if not exists "order" int;

values ('b14567dc-5f0b-4dd3-9e95-9fd54ea4c949', 1, 1, 'The Psychology of Spending', null)
on conflict (id) do nothing;

on conflict (id) do nothing;



-- Public read access for curriculum content -- these tables hold no
-- student data, so it's safe to open read-only ahead of the auth/RLS
-- policy work still to come for the student-specific tables.
create policy "Public read access" on topics for select using (true);
create policy "Public read access" on subtopics for select using (true);
create policy "Public read access" on slides for select using (true);
create policy "Public read access" on questions for select using (true);
